import pathlib,yaml
def contains(actual,desired):
    if isinstance(desired,dict):return isinstance(actual,dict) and all(k in actual and contains(actual[k],v) for k,v in desired.items())
    if isinstance(desired,list):return isinstance(actual,list) and len(actual)==len(desired) and all(contains(a,b) for a,b in zip(actual,desired))
    return actual==desired
def apply_config(base,path,candidate,request):
    before=request("GET",base+"/api/v2/status")[1]["config"]["original"]
    pathlib.Path(path).write_text(candidate,encoding="utf8")
    status,_=request("POST",base+"/-/reload")
    effective=request("GET",base+"/api/v2/status")[1]["config"]["original"]
    metrics=request("GET",base+"/metrics")[1]
    line=next(x for x in metrics.splitlines() if x.startswith("alertmanager_config_last_reload_successful "))
    success=float(line.split()[1])==1
    if status!=200:
        if success or yaml.safe_load(effective)!=yaml.safe_load(before):raise RuntimeError("rejected reload changed effective configuration")
        return {"applied":False,"effective":yaml.safe_load(effective),"reload_success":False}
    active=yaml.safe_load(effective);desired=yaml.safe_load(candidate)
    if not success or not contains(active["route"],desired["route"]) or [x["name"] for x in active["receivers"]]!=[x["name"] for x in desired["receivers"]]:raise RuntimeError("visible runtime route does not match approved candidate")
    return {"applied":True,"effective":yaml.safe_load(effective),"reload_success":True}
